import { type SynapseEnhancedHttpClient, SynapseEnhancedError } from "./http.ts";
import { ErrorCode } from "./error-codes.ts";
import { handleApiResponse } from "./response-formatter.ts";

export abstract class BaseApi {
    public constructor(protected readonly httpClient: SynapseEnhancedHttpClient) {}

    protected async get<T>(
        endpoint: string,
        params?: unknown,
        errorMessage: string = "GET request failed",
    ): Promise<T> {
        const response = await this.httpClient.request<{ status: string | number; data?: T; error?: string }>(
            endpoint,
            {
                method: "GET",
                queryParams: params as Record<string, string | number | boolean | null | undefined>,
            },
        );
        return handleApiResponse(response, errorMessage);
    }

    protected async post<T>(
        endpoint: string,
        body?: unknown,
        errorMessage: string = "POST request failed",
    ): Promise<T> {
        const response = await this.httpClient.request<{ status: string | number; data?: T; error?: string }>(
            endpoint,
            {
                method: "POST",
                body: body as Record<string, unknown>,
            },
        );
        return handleApiResponse(response, errorMessage);
    }

    protected async put<T>(endpoint: string, body?: unknown, errorMessage: string = "PUT request failed"): Promise<T> {
        const response = await this.httpClient.request<{ status: string | number; data?: T; error?: string }>(
            endpoint,
            {
                method: "PUT",
                body: body as Record<string, unknown>,
            },
        );
        return handleApiResponse(response, errorMessage);
    }

    protected async deleteRequest<T>(
        endpoint: string,
        params?: unknown,
        errorMessage: string = "DELETE request failed",
    ): Promise<T> {
        const response = await this.httpClient.request<{ status: string | number; data?: T; error?: string }>(
            endpoint,
            {
                method: "DELETE",
                queryParams: params as Record<string, string | number | boolean | null | undefined>,
            },
        );
        return handleApiResponse(response, errorMessage);
    }

    protected async patch<T>(
        endpoint: string,
        body?: unknown,
        errorMessage: string = "PATCH request failed",
    ): Promise<T> {
        const response = await this.httpClient.request<{ status: string | number; data?: T; error?: string }>(
            endpoint,
            {
                method: "PATCH",
                body: body as Record<string, unknown>,
            },
        );
        return handleApiResponse(response, errorMessage);
    }

    protected handleResponse<T>(response: { data?: T; status: number }, errorMessage: string): T {
        if (!response.data) {
            throw new SynapseEnhancedError(errorMessage, ErrorCode.UNKNOWN, undefined, response.status);
        }
        return response.data;
    }

    protected createError(
        message: string,
        code: ErrorCode,
        detail?: Record<string, unknown>,
        statusCode: number = 500,
    ): never {
        throw new SynapseEnhancedError(message, code, detail, statusCode);
    }

    protected throwRateLimitError(retryAfterSeconds: number): never {
        const detail = { retry_after_ms: Math.max(0, Math.floor(retryAfterSeconds * 1000)) };
        throw new SynapseEnhancedError("Rate limit exceeded", ErrorCode.LIMIT_EXCEEDED, detail, 429, true);
    }

    protected async withRetry<T>(
        operation: () => Promise<T>,
        maxRetries: number = 3,
        delay: number = 1000,
    ): Promise<T> {
        let lastError: unknown;
        for (let attempt = 0; attempt <= maxRetries; attempt++) {
            try {
                return await operation();
            } catch (error) {
                lastError = error;
                if (attempt < maxRetries) {
                    await new Promise((resolve) => setTimeout(resolve, delay * Math.pow(2, attempt)));
                }
            }
        }
        throw lastError;
    }
}
